// The warp destinations: areas in menu order, and the spots in each. Every spot is a point where the game itself
// places Link (a loading-zone arrival, a warp-song arrival, a return point, a mini-game start or a story position),
// so none is out of bounds. The data is generated by catalog.py from the game's map files (destinations.inc); the
// same run writes DESTINATIONS.md, the table for people. Each spot also has a place (one of the game's
// visited-places flags), used only by the visited-places build.
#pragma once

#include "game.hpp"

namespace warp {

enum class Age : u8 { Young, Adult };

struct Area {
    const char* banc;   // GameBancParam name, written to the reserved next-area slot
    const char* title;  // shown in the menu
    Age age;            // the age whose world this map is
    int first;          // index of its first spot in kSpots
    int count;          // its spots
};

struct Spot {
    const char* label;  // shown in the menu
    const char* spawn;  // named spawn point (StartPos), or "" to arrive by position
    float position[3];  // the point's position; written only when spawn is ""
};

// A loading zone, for the visited-places build: arriving where it leads (arrival, the record name of the destination
// area and spawn point) from the spot's area also shows the spot, the zone's own side.
struct Doorway {
    u32 arrival;
    u16 spot;  // index into kSpots
};

#include "destinations.inc"

inline constexpr int kAreaCount = sizeof(kAreas) / sizeof(kAreas[0]);
inline constexpr int kSpotCount = sizeof(kSpots) / sizeof(kSpots[0]);
inline constexpr int kPlaceCount = sizeof(kPlaceFlags) / sizeof(kPlaceFlags[0]);

constexpr bool spotPlacesValid() {
    for (const u8 place : kSpotPlace) {
        if (place >= kPlaceCount) { return false; }
    }
    return true;
}
static_assert(sizeof(kSpotPlace) == kSpotCount && spotPlacesValid(), "every spot has one of the listed places");
static_assert(sizeof(kSpotKey) / sizeof(kSpotKey[0]) == kSpotCount, "every spot has a record name");

constexpr bool doorwaysValid() {
    for (const Doorway& doorway : kDoorways) {
        if (doorway.spot >= kSpotCount) { return false; }
    }
    return true;
}
static_assert(doorwaysValid(), "every loading zone's own side is a listed spot");
static_assert(kPlaceCount <= 64, "the visited places fit one 64-bit mask");

constexpr bool areasCoverSpots() {
    int next = 0;
    for (const Area& area : kAreas) {
        if (area.first != next || area.count <= 0) { return false; }
        next += area.count;
    }
    return next == kSpotCount;
}
static_assert(areasCoverSpots(), "each area's spots follow the previous area's, with none left over");

// Each age's areas form one run of kAreas (young first); the menu shows one age's list at a time.
constexpr int ageFirst(Age age) {
    for (int i = 0; i < kAreaCount; ++i) {
        if (kAreas[i].age == age) { return i; }
    }
    return kAreaCount;
}

constexpr int ageCount(Age age) {
    int n = 0;
    for (const Area& area : kAreas) { n += area.age == age ? 1 : 0; }
    return n;
}

constexpr bool agesContiguous() {
    for (const Age age : {Age::Young, Age::Adult}) {
        const int first = ageFirst(age), count = ageCount(age);
        if (count <= 0) { return false; }
        for (int i = first; i < first + count; ++i) {
            if (kAreas[i].age != age) { return false; }
        }
    }
    return true;
}
static_assert(agesContiguous(), "each age's areas are listed together");

constexpr Age otherAge(Age age) { return age == Age::Young ? Age::Adult : Age::Young; }
constexpr const char* ageName(Age age) { return age == Age::Young ? "young" : "adult"; }

}  // namespace warp
